import sqlite3
c=sqlite3.connect('claims.sqlite'); c.row_factory=sqlite3.Row
pol={r['policy_id']:dict(r) for r in c.execute('select * from policies')}
items={};pays={}
for r in c.execute('select * from claim_items'): items.setdefault(r['claim_id'],[]).append(dict(r))
for r in c.execute('select * from claim_payments'): pays.setdefault(r['claim_id'],[]).append(dict(r))
for r in c.execute('select * from claims'):
    d=dict(r); p=pol[d['policy_id']]
    print('=====',d['claim_id'],{k:v for k,v in d.items() if v is not None and k!='claim_id'})
    print(' POL',{k:v for k,v in p.items() if v is not None and k not in('insured_risks','postcode','annual_premium_gbp','claims_declared_5y','exclusions')})
    for i in items.get(d['claim_id'],[]): print(' ITEM',{k:v for k,v in i.items() if v is not None and k not in('claim_id',)})
    for i in pays.get(d['claim_id'],[]): print(' PAY',{k:v for k,v in i.items() if v is not None and k not in('claim_id',)})
E
wc <agent-scratch>/scratchpad/dump.txt
